begin;

-- Seed the remaining AP Calculus AB and AP Biology topic point briefs.
-- Existing Unit 1 briefs remain authored in
-- 20260820192400_student_readable_taxonomy_and_topic_guides.sql.

with brief_seed (
  subject_key, unit_number, topic_code, title, class_importance, exam_importance,
  what_it_is, why_it_matters, how_points_are_earned, answer_move,
  common_point_loss, learn_more_slug
) as (
  values
  ($$ap_calculus_ab$$,2,$$2.1$$,$$Defining Average and Instantaneous Rates of Change at a Point$$,$$very-important$$,$$very-important$$,$$Average rate compares total change over an interval, while instantaneous rate describes the limiting rate at one input.$$, $$This is the bridge from limits to derivatives and appears whenever slope, velocity, or change at an instant is being interpreted.$$, $$You earn points by distinguishing interval-based average rate from point-based instantaneous rate and by setting up the correct difference quotient or limiting interpretation.$$, $$Name the quantity first: average over an interval or instantaneous at a point. Then use a secant slope or tangent-slope limit accordingly.$$, $$Using the average rate formula when the question asks for the rate at one instant.$$, $$average-and-instantaneous-rates$$),
  ($$ap_calculus_ab$$,2,$$2.2$$,$$Defining the Derivative of a Function and Using Derivative Notation$$,$$very-important$$,$$very-important$$,$$The derivative is the limit of the difference quotient and represents instantaneous rate of change or tangent-line slope.$$, $$Derivative notation becomes the language for nearly every later unit, including motion, optimization, differential equations, and accumulation.$$, $$You earn points by writing correct derivative notation, interpreting it in context, and connecting the derivative to a limit or slope.$$, $$Translate f'(a) as the instantaneous rate of change of f with respect to x at x = a.$$, $$Treating f'(a) as a y-value of the original function instead of as a rate or slope.$$, $$derivative-definition-and-notation$$),
  ($$ap_calculus_ab$$,2,$$2.3$$,$$Estimating Derivatives of a Function at a Point$$,$$very-important$$,$$very-important$$,$$A derivative can be estimated from nearby graph or table values when an exact formula is not available.$$, $$Many AP tasks ask students to reason from data, so derivative estimates must be tied to local slope evidence.$$, $$You earn points by choosing nearby points, computing a reasonable local rate, and labeling the estimate with units when the context has units.$$, $$Use the closest available values around the point and describe the estimate as a local slope.$$, $$Using distant data values or failing to distinguish an estimate from an exact derivative.$$, $$estimating-derivatives$$),
  ($$ap_calculus_ab$$,2,$$2.4$$,$$Connecting Differentiability and Continuity$$,$$very-important$$,$$very-important$$,$$Differentiability at a point means a derivative exists there, and differentiability implies continuity at that point.$$, $$This topic prevents invalid derivative claims at corners, cusps, vertical tangents, jumps, and holes.$$, $$You earn points by checking whether the function is continuous and whether the local slope behavior has one consistent finite value.$$, $$Use the chain: differentiable -> continuous. If continuity fails, differentiability fails too.$$, $$Claiming a derivative exists at a corner or discontinuity because the graph has points on both sides.$$, $$differentiability-and-continuity$$),
  ($$ap_calculus_ab$$,2,$$2.5$$,$$Applying the Power Rule$$,$$very-important$$,$$very-important$$,$$The power rule differentiates x^n by multiplying by the exponent and reducing the exponent by one.$$, $$It is the most common derivative tool and supports later work with motion, optimization, and graph analysis.$$, $$You earn points by applying the exponent change accurately, including negative and fractional powers after rewriting radicals or reciprocals.$$, $$Rewrite the expression as powers of x first, then apply d/dx x^n = n x^(n-1).$$, $$Dropping coefficients or mishandling negative and fractional exponents.$$, $$power-rule$$),
  ($$ap_calculus_ab$$,2,$$2.6$$,$$Derivative Rules: Constant, Sum, Difference, and Constant Multiple$$,$$very-important$$,$$very-important$$,$$These rules let students differentiate expressions term by term while preserving coefficients and signs.$$, $$Most derivative calculations depend on these rules even when another major rule is also needed.$$, $$You earn points by separating terms correctly, carrying constants through the derivative, and making the derivative of a constant zero.$$, $$Differentiate one term at a time and keep every coefficient and sign visible until the end.$$, $$Forgetting that constants differentiate to zero or changing signs during term-by-term work.$$, $$basic-derivative-rules$$),
  ($$ap_calculus_ab$$,2,$$2.7$$,$$Derivatives of cos x, sin x, e^x, and ln x$$,$$very-important$$,$$very-important$$,$$These are foundational derivative facts for trigonometric, exponential, and logarithmic functions.$$, $$They appear throughout applied and analytical problems, often inside product, quotient, and chain rule expressions.$$, $$You earn points by recalling the correct base derivative and combining it with other rules when the expression is more complex.$$, $$Identify the function family first, then apply its derivative fact before simplifying.$$, $$Changing the sign of the trig derivative incorrectly or treating ln x like 1/x only after forgetting domain context.$$, $$core-transcendental-derivatives$$),
  ($$ap_calculus_ab$$,2,$$2.8$$,$$The Product Rule$$,$$very-important$$,$$very-important$$,$$The product rule differentiates a product by differentiating each factor once while leaving the other factor unchanged.$$, $$Many AP expressions are products designed to test whether students choose structure-aware differentiation instead of distributing or guessing.$$, $$You earn points by showing both product-rule terms and applying any needed inner derivative inside each factor.$$, $$Write first times derivative of second plus second times derivative of first before simplifying.$$, $$Differentiating both factors at once or omitting one of the two product-rule terms.$$, $$product-rule$$),
  ($$ap_calculus_ab$$,2,$$2.9$$,$$The Quotient Rule$$,$$very-important$$,$$very-important$$,$$The quotient rule differentiates a ratio by combining the derivative of the numerator and denominator over the denominator squared.$$, $$It is a frequent source of sign and order errors, especially when quotient structure is nested inside applied questions.$$, $$You earn points by preserving the quotient-rule order, squaring the denominator, and simplifying only after the derivative structure is correct.$$, $$Use low d-high minus high d-low over low squared, then check signs before simplifying.$$, $$Reversing the numerator terms or forgetting to square the denominator.$$, $$quotient-rule$$),
  ($$ap_calculus_ab$$,2,$$2.10$$,$$Derivatives of tan x, cot x, sec x, and csc x$$,$$somewhat-important$$,$$somewhat-important$$,$$These derivative facts extend trig differentiation beyond sine and cosine.$$, $$They are less central than sine and cosine but can appear in calculation-heavy derivative tasks and later antiderivative recognition.$$, $$You earn points by recalling the correct trig derivative and sign, then combining it with product, quotient, or chain rule structure if needed.$$, $$Pair each trig function with its derivative fact before doing any algebraic simplification.$$, $$Mixing up the signs for cot x and csc x or confusing sec x tan x with sec^2 x.$$, $$secondary-trig-derivatives$$),
  ($$ap_calculus_ab$$,3,$$3.1$$,$$The Chain Rule$$,$$very-important$$,$$very-important$$,$$The chain rule differentiates composite functions by multiplying the derivative of the outside function by the derivative of the inside function.$$, $$It is one of the highest-leverage skills in calculus because most nontrivial derivatives include nested structure.$$, $$You earn points by identifying inside and outside functions and including the inner derivative factor.$$, $$Circle the inside expression, differentiate the outside around it, then multiply by the derivative of the inside.$$, $$Differentiating the outside function but forgetting the inner derivative.$$, $$chain-rule$$),
  ($$ap_calculus_ab$$,3,$$3.2$$,$$Implicit Differentiation$$,$$very-important$$,$$very-important$$,$$Implicit differentiation finds dy/dx when x and y are related by an equation that is not solved for y.$$, $$It allows students to analyze curves and rates where y is mixed with x, which appears in tangent-line and related-rate problems.$$, $$You earn points by differentiating both sides with respect to x and attaching dy/dx whenever differentiating a y-expression.$$, $$Differentiate term by term, mark every y-derivative with dy/dx, then solve algebraically for dy/dx.$$, $$Forgetting the dy/dx factor on terms involving y.$$, $$implicit-differentiation$$),
  ($$ap_calculus_ab$$,3,$$3.3$$,$$Differentiating Inverse Functions$$,$$somewhat-important$$,$$somewhat-important$$,$$The derivative of an inverse function is tied to the reciprocal of the derivative of the original function at the corresponding point.$$, $$This topic strengthens students' ability to coordinate x-values, y-values, and inverse relationships across representations.$$, $$You earn points by matching the inverse input to the original output and using the reciprocal derivative at the matching original input.$$, $$Find the point on f that corresponds to the inverse input, then take 1/f'(that x-value).$$, $$Using the reciprocal at the wrong x-value or confusing f inverse with 1/f.$$, $$inverse-function-derivatives$$),
  ($$ap_calculus_ab$$,3,$$3.4$$,$$Differentiating Inverse Trigonometric Functions$$,$$somewhat-important$$,$$somewhat-important$$,$$Inverse trigonometric derivatives have specific algebraic forms that often combine with the chain rule.$$, $$They appear less often than core derivative rules but can decide points in mixed derivative questions.$$, $$You earn points by selecting the correct inverse trig derivative formula and applying the inner derivative when the argument is not just x.$$, $$Identify the inverse trig function, write its derivative template, then substitute the inside expression and multiply by its derivative.$$, $$Forgetting the chain rule or confusing arcsin, arctan, and arcsec denominator forms.$$, $$inverse-trig-derivatives$$),
  ($$ap_calculus_ab$$,3,$$3.5$$,$$Selecting Procedures for Calculating Derivatives$$,$$very-important$$,$$very-important$$,$$This topic is about choosing which derivative rule or combination of rules fits the structure of a function.$$, $$AP derivative questions often test rule selection more than arithmetic once the student sees the structure clearly.$$, $$You earn points by matching product, quotient, chain, implicit, or basic rules to the expression before calculating.$$, $$Pause before differentiating and name the outer structure: sum, product, quotient, composition, or implicit relation.$$, $$Applying a familiar rule to the whole expression without checking the actual structure.$$, $$selecting-derivative-procedures$$),
  ($$ap_calculus_ab$$,3,$$3.6$$,$$Calculating Higher-Order Derivatives$$,$$very-important$$,$$very-important$$,$$Higher-order derivatives are derivatives of derivatives, such as second derivative and beyond.$$, $$They carry important meaning for acceleration, concavity, and graph behavior throughout later units.$$, $$You earn points by differentiating repeatedly while keeping notation clear and interpreting each derivative in context when asked.$$, $$Compute one derivative at a time and label f', f'', or the requested order before substituting values.$$, $$Substituting too early or losing track of which derivative the question asks for.$$, $$higher-order-derivatives$$),
  ($$ap_calculus_ab$$,4,$$4.1$$,$$Interpreting the Meaning of the Derivative in Context$$,$$very-important$$,$$very-important$$,$$A derivative in context is a rate of change with units and a specific meaning tied to the quantities in the problem.$$, $$FRQs frequently award points for interpretation, not only computation, and the wording must match the scenario.$$, $$You earn points by stating what is changing, with respect to what, at what input, and in what units.$$, $$Use the sentence frame: at x = a, the quantity is changing at about/value units of output per unit of input.$$, $$Giving a numeric derivative without units or contextual meaning.$$, $$derivative-in-context$$),
  ($$ap_calculus_ab$$,4,$$4.2$$,$$Straight-Line Motion: Connecting Position, Velocity, and Acceleration$$,$$very-important$$,$$very-important$$,$$Position, velocity, and acceleration are connected by derivatives: velocity is position's derivative and acceleration is velocity's derivative.$$, $$Motion questions are a major AP context for derivative interpretation, sign, speed, and direction.$$, $$You earn points by using the correct derivative relationship and interpreting sign and magnitude in the context of motion.$$, $$Write the chain s(t) -> v(t) -> a(t), then decide whether the question asks for position, direction, speed, or acceleration.$$, $$Confusing velocity with speed or treating negative velocity as slower instead of direction-dependent.$$, $$position-velocity-acceleration$$),
  ($$ap_calculus_ab$$,4,$$4.3$$,$$Rates of Change in Applied Contexts Other Than Motion$$,$$very-important$$,$$very-important$$,$$Derivatives describe rates in contexts such as volume, population, temperature, cost, and concentration.$$, $$Students need to transfer derivative reasoning beyond motion and preserve units and meaning.$$, $$You earn points by identifying the dependent and independent variables and expressing the derivative as a contextual rate.$$, $$Translate dy/dx as change in y per change in x, then attach the problem's units.$$, $$Writing a derivative symbol or value without saying what real-world rate it represents.$$, $$applied-rates-of-change$$),
  ($$ap_calculus_ab$$,4,$$4.4$$,$$Introduction to Related Rates$$,$$very-important$$,$$very-important$$,$$Related rates problems connect multiple changing quantities through an equation and differentiate with respect to time.$$, $$They are an important FRQ pattern because points come from setup, differentiation, substitution, and interpretation.$$, $$You earn points by defining variables, writing the relationship before differentiating, and distinguishing known rates from the requested rate.$$, $$Draw or define the variables, write the equation, differentiate with respect to time, then substitute known values.$$, $$Substituting values before differentiating or mixing up variables with their rates.$$, $$related-rates-introduction$$),
  ($$ap_calculus_ab$$,4,$$4.5$$,$$Solving Related Rates Problems$$,$$very-important$$,$$very-important$$,$$Solving related rates means carrying the setup through implicit differentiation and algebra to find the requested rate.$$, $$These problems reward clear process and units, making them strong point opportunities even when the arithmetic is not simple.$$, $$You earn points by showing the model equation, differentiating correctly, substituting time-specific values, and answering with units.$$, $$Keep d/dt visible through the differentiation step, then plug in the snapshot values after the derivative equation is formed.$$, $$Answering for the wrong rate or using a value that belongs to a different time.$$, $$solving-related-rates$$),
  ($$ap_calculus_ab$$,4,$$4.6$$,$$Approximating Values of a Function Using Local Linearity and Linearization$$,$$very-important$$,$$very-important$$,$$Linearization uses the tangent line near a point to approximate nearby function values.$$, $$AP questions use this to connect derivatives to approximation, error reasoning, and readable tangent-line equations.$$, $$You earn points by building L(x) = f(a) + f'(a)(x-a), substituting the nearby input, and stating that it is an approximation.$$, $$Find f(a) and f'(a), write the tangent-line model, then evaluate the nearby x-value.$$, $$Using a secant line or forgetting that the approximation is anchored at the given point a.$$, $$local-linearity-and-linearization$$),
  ($$ap_calculus_ab$$,4,$$4.7$$,$$Using L'Hospital's Rule for Determining Limits of Indeterminate Forms$$,$$very-important$$,$$very-important$$,$$L'Hospital's Rule evaluates certain indeterminate limits by comparing derivatives of numerator and denominator.$$, $$It lets students resolve limits that connect derivative tools back to Unit 1 limit questions.$$, $$You earn points by first verifying an indeterminate form such as 0/0 or infinity/infinity, then differentiating numerator and denominator separately.$$, $$State the indeterminate form, apply L'Hospital's Rule, then evaluate the new limit.$$, $$Applying the rule without verifying the form or using quotient rule instead of differentiating numerator and denominator separately.$$, $$lhospitals-rule$$),
  ($$ap_calculus_ab$$,5,$$5.1$$,$$Using the Mean Value Theorem$$,$$very-important$$,$$very-important$$,$$The Mean Value Theorem connects an average rate over an interval to at least one matching instantaneous rate inside the interval.$$, $$It is a theorem-based justification topic and often appears in explanation-heavy questions.$$, $$You earn points by checking continuity and differentiability conditions, computing the average rate, and stating the guaranteed c-value conclusion.$$, $$Verify conditions first, then set f'(c) equal to the secant slope.$$, $$Using the theorem without stating continuity on the closed interval and differentiability on the open interval.$$, $$mean-value-theorem$$),
  ($$ap_calculus_ab$$,5,$$5.2$$,$$Extreme Value Theorem, Global Versus Local Extrema, and Critical Points$$,$$very-important$$,$$very-important$$,$$This topic distinguishes absolute extrema, local extrema, and critical points where extrema may occur.$$, $$It supports graph analysis, optimization, and justification of maximum and minimum values.$$, $$You earn points by finding critical points, considering endpoints when needed, and using the correct vocabulary for local versus absolute behavior.$$, $$List candidates from critical points and endpoints, then compare values if the question asks for absolute extrema.$$, $$Ignoring endpoints or calling every critical point a maximum or minimum.$$, $$extrema-and-critical-points$$),
  ($$ap_calculus_ab$$,5,$$5.3$$,$$Determining Intervals on Which a Function Is Increasing or Decreasing$$,$$very-important$$,$$very-important$$,$$A function increases where its derivative is positive and decreases where its derivative is negative.$$, $$This is a core link between derivative sign and function behavior used across graph and FRQ reasoning.$$, $$You earn points by testing derivative sign on intervals and translating that sign into increasing or decreasing behavior.$$, $$Make a sign chart for f' and state intervals using x-values, not y-values.$$, $$Using f-values instead of derivative signs to decide increasing or decreasing intervals.$$, $$increasing-and-decreasing$$),
  ($$ap_calculus_ab$$,5,$$5.4$$,$$Using the First Derivative Test$$,$$very-important$$,$$very-important$$,$$The first derivative test classifies local extrema by how f' changes sign around a critical point.$$, $$It is a point-rich justification pattern because the conclusion depends on evidence on both sides.$$, $$You earn points by showing f' changes from positive to negative for a local maximum or negative to positive for a local minimum.$$, $$Check f' on the left and right of the critical point before naming the extremum.$$, $$Saying f'(c)=0 is enough to prove a maximum or minimum.$$, $$first-derivative-test$$),
  ($$ap_calculus_ab$$,5,$$5.5$$,$$Using the Candidates Test to Determine Absolute Extrema$$,$$very-important$$,$$very-important$$,$$The candidates test compares function values at endpoints and critical points to identify absolute extrema on a closed interval.$$, $$It is one of the clearest AP workflows for earning all extrema points with organized work.$$, $$You earn points by identifying all candidates, evaluating the original function at each one, and selecting the largest or smallest value.$$, $$Build a candidates table: endpoints plus interior critical points, then compare f-values.$$, $$Comparing derivative values instead of function values or omitting endpoints.$$, $$candidates-test$$),
  ($$ap_calculus_ab$$,5,$$5.6$$,$$Determining Concavity$$,$$very-important$$,$$very-important$$,$$Concavity describes whether slopes are increasing or decreasing and is determined by the sign of the second derivative.$$, $$It connects derivative behavior to graph shape and prepares students for inflection and second-derivative reasoning.$$, $$You earn points by finding where f'' is positive or negative and translating that sign into concave up or concave down intervals.$$, $$Make a sign chart for f'' and state concavity on intervals.$$, $$Using f' sign to decide concavity instead of f'' sign.$$, $$concavity$$),
  ($$ap_calculus_ab$$,5,$$5.7$$,$$Using the Second Derivative Test$$,$$somewhat-important$$,$$somewhat-important$$,$$The second derivative test can classify certain critical points using the sign of f'' at the point.$$, $$It is efficient when it applies, but students must know its limits when f'' is zero or undefined.$$, $$You earn points by confirming f'(c)=0 or undefined as needed and then using f''(c) to classify the local behavior when possible.$$, $$Check the critical point first, then use f''(c)>0 for local minimum or f''(c)<0 for local maximum.$$, $$Using the test when f''(c)=0 and treating an inconclusive result as a conclusion.$$, $$second-derivative-test$$),
  ($$ap_calculus_ab$$,5,$$5.8$$,$$Sketching Graphs of Functions and Their Derivatives$$,$$very-important$$,$$very-important$$,$$Graph sketching connects function values, derivative signs, slope behavior, extrema, and concavity into one representation.$$, $$AP graph tasks reward coordination across f, f', and f'' rather than isolated calculations.$$, $$You earn points by using derivative evidence to place increasing/decreasing intervals, extrema, concavity, and inflection behavior correctly.$$, $$Annotate the derivative evidence first, then sketch only what the evidence supports.$$, $$Drawing a graph from intuition without tying features to derivative sign or second-derivative sign.$$, $$sketching-functions-and-derivatives$$),
  ($$ap_calculus_ab$$,5,$$5.9$$,$$Connecting a Function, Its First Derivative, and Its Second Derivative$$,$$very-important$$,$$very-important$$,$$This topic asks students to translate among f, f', and f'' in graphs, tables, and symbolic forms.$$, $$It is central to AP reasoning because many questions give one representation and ask about another.$$, $$You earn points by connecting f' to slope and f'' to change in slope, then using those links to justify behavior.$$, $$Ask which graph or table represents values, slopes, or changes in slopes before answering.$$, $$Confusing the graph of f with the graph of f' when identifying extrema or concavity.$$, $$connecting-f-fprime-fdoubleprime$$),
  ($$ap_calculus_ab$$,5,$$5.10$$,$$Introduction to Optimization Problems$$,$$very-important$$,$$very-important$$,$$Optimization uses derivatives to find maximum or minimum values of a quantity under given constraints.$$, $$It turns derivative analysis into applied decision-making and is a common FRQ-style setup.$$, $$You earn points by defining the quantity to optimize, writing it as a one-variable function, and identifying the relevant domain.$$, $$Define variables, write the objective function, use the constraint to reduce to one variable, then state the domain.$$, $$Differentiating before creating a valid one-variable objective function.$$, $$optimization-introduction$$),
  ($$ap_calculus_ab$$,5,$$5.11$$,$$Solving Optimization Problems$$,$$very-important$$,$$very-important$$,$$Solving optimization problems means finding candidates, testing them, and interpreting the best value in context.$$, $$These are high-value AP tasks because setup, derivative work, justification, and interpretation can each earn points.$$, $$You earn points by differentiating the objective, finding critical points in the domain, justifying max or min, and answering the contextual question.$$, $$After setup, solve f'(x)=0, test candidates, then answer with units and the requested variable.$$, $$Finding a critical point but not proving it gives the requested maximum or minimum.$$, $$solving-optimization$$),
  ($$ap_calculus_ab$$,5,$$5.12$$,$$Exploring Behaviors of Implicit Relations$$,$$somewhat-important$$,$$somewhat-important$$,$$Implicit relations can have slopes, extrema, and concavity even when they are not written as y = f(x).$$, $$This topic extends derivative-based graph analysis to curves where x and y are intertwined.$$, $$You earn points by using implicit differentiation to obtain dy/dx and then applying behavior rules to the relation.$$, $$Differentiate implicitly, solve for dy/dx, then evaluate slope or behavior at the specified point.$$, $$Trying to treat y as a constant or assuming the relation is already solved for y.$$, $$implicit-relation-behavior$$),
  ($$ap_calculus_ab$$,6,$$6.1$$,$$Exploring Accumulations of Change$$,$$very-important$$,$$very-important$$,$$Accumulation describes how small changes add up over an interval.$$, $$It introduces the integral as a total-change idea before students focus on symbolic integration.$$, $$You earn points by interpreting a rate over an interval as accumulated change and connecting area under a rate graph to total amount.$$, $$Identify the rate, identify the interval, then describe the accumulation as total change over that interval.$$, $$Treating the rate value at one point as the accumulated total over an interval.$$, $$accumulations-of-change$$),
  ($$ap_calculus_ab$$,6,$$6.2$$,$$Approximating Areas with Riemann Sums$$,$$very-important$$,$$very-important$$,$$Riemann sums approximate accumulated area using rectangles based on left, right, midpoint, or other sample values.$$, $$They are a common table-based way to earn accumulation points without an antiderivative.$$, $$You earn points by choosing the correct subinterval widths and sample heights, then summing width times height with units.$$, $$For each subinterval, compute base times chosen height, then add the products.$$, $$Using the wrong endpoint or assuming all subintervals have equal width when they do not.$$, $$riemann-sum-area-approximations$$),
  ($$ap_calculus_ab$$,6,$$6.3$$,$$Riemann Sums, Summation Notation, and Definite Integral Notation$$,$$very-important$$,$$very-important$$,$$This topic connects rectangle sums, sigma notation, and definite integrals as representations of accumulated change.$$, $$Students need to move among numeric, symbolic, and notation forms to read AP prompts accurately.$$, $$You earn points by matching limits of integration, subinterval structure, and integrand meaning to the accumulation being represented.$$, $$Translate the notation into total accumulation from a to b of the rate or height function.$$, $$Misreading the bounds or treating definite integral notation as an antiderivative request only.$$, $$riemann-sums-and-integral-notation$$),
  ($$ap_calculus_ab$$,6,$$6.4$$,$$The Fundamental Theorem of Calculus and Accumulation Functions$$,$$very-important$$,$$very-important$$,$$The Fundamental Theorem of Calculus links accumulation functions to derivatives of their integrands.$$, $$It is a central bridge between differentiation and integration and appears in many graph/table FRQs.$$, $$You earn points by recognizing that the derivative of an accumulation function depends on the integrand and any variable bound behavior.$$, $$For F(x)=integral from a to x of f(t)dt, write F'(x)=f(x); adjust with chain rule if the bound is not x.$$, $$Replacing the accumulation function with a number or forgetting the chain rule for variable bounds.$$, $$ftc-accumulation-functions$$),
  ($$ap_calculus_ab$$,6,$$6.5$$,$$Interpreting the Behavior of Accumulation Functions$$,$$very-important$$,$$very-important$$,$$Accumulation functions increase or decrease based on the sign of the rate being accumulated, and their concavity depends on how that rate changes.$$, $$This topic turns integral notation into graph behavior, a frequent AP representation shift.$$, $$You earn points by connecting the integrand to the derivative of the accumulation function and then reasoning about sign or slope.$$, $$Treat the integrand as F'(x), then use derivative-sign logic to discuss F.$$, $$Judging the accumulation function directly from the area picture without using the integrand as its derivative.$$, $$behavior-of-accumulation-functions$$),
  ($$ap_calculus_ab$$,6,$$6.6$$,$$Applying Properties of Definite Integrals$$,$$very-important$$,$$very-important$$,$$Definite integral properties allow students to split, combine, reverse, and scale accumulated quantities.$$, $$These properties are heavily used when graphs or tables provide partial areas instead of formulas.$$, $$You earn points by applying interval additivity, sign reversal, constant multiples, and symmetry when appropriate.$$, $$Rewrite the requested integral in terms of known intervals or areas before calculating.$$, $$Adding areas without accounting for sign or reversed bounds.$$, $$definite-integral-properties$$),
  ($$ap_calculus_ab$$,6,$$6.7$$,$$The Fundamental Theorem of Calculus and Definite Integrals$$,$$very-important$$,$$very-important$$,$$The evaluation part of the Fundamental Theorem of Calculus uses antiderivatives to compute exact definite integrals.$$, $$It provides the main exact method for total change and area when an antiderivative is available.$$, $$You earn points by finding a valid antiderivative, evaluating it at the bounds, and subtracting upper minus lower.$$, $$Find F, then compute F(b)-F(a) and attach contextual units when the integral represents change.$$, $$Subtracting in the wrong order or forgetting that a definite integral can be negative when it represents signed change.$$, $$ftc-definite-integrals$$),
  ($$ap_calculus_ab$$,6,$$6.8$$,$$Finding Antiderivatives and Indefinite Integrals$$,$$very-important$$,$$very-important$$,$$An antiderivative reverses differentiation, and an indefinite integral represents a family of functions.$$, $$This skill underlies exact accumulation, differential equation solutions, and many applied models.$$, $$You earn points by using correct reverse derivative rules and including +C for indefinite integrals.$$, $$Ask what function would differentiate to this expression, then include the constant of integration when no bounds are present.$$, $$Forgetting +C or applying derivative rules forward instead of reversing them.$$, $$antiderivatives-and-indefinite-integrals$$),
  ($$ap_calculus_ab$$,6,$$6.9$$,$$Integrating Using Substitution$$,$$very-important$$,$$very-important$$,$$Substitution reverses the chain rule by changing variables so a composite integrand becomes simpler.$$, $$It is one of the most common integration techniques on the AP exam.$$, $$You earn points by choosing u, computing du, rewriting the integral consistently, and adjusting bounds for definite integrals when used.$$, $$Choose the inside expression as u, find du, rewrite everything in u, then integrate.$$, $$Leaving a mix of x and u in the same integral or forgetting to adjust definite bounds.$$, $$integration-by-substitution$$),
  ($$ap_calculus_ab$$,6,$$6.10$$,$$Integrating Functions Using Long Division and Completing the Square$$,$$somewhat-important$$,$$somewhat-important$$,$$Some rational expressions must be rewritten by long division or completing the square before integration.$$, $$This topic tests whether students can prepare an expression for a familiar antiderivative form.$$, $$You earn points by rewriting the integrand into an equivalent form and then applying the appropriate antiderivative rule.$$, $$When the integral does not match a basic form, rewrite the algebra first, then integrate the simpler pieces.$$, $$Trying to integrate a complicated rational expression directly without making the needed algebraic rewrite.$$, $$integration-long-division-completing-square$$),
  ($$ap_calculus_ab$$,6,$$6.11$$,$$Integrating Using Integration by Parts$$,$$somewhat-important$$,$$somewhat-important$$,$$Integration by parts rewrites an integral of a product using a derivative-antiderivative tradeoff.$$, $$It is less common for AB than substitution but important where the local taxonomy includes product-structured antiderivatives.$$, $$You earn points by choosing u and dv, computing du and v, and applying integral u dv = uv - integral v du accurately.$$, $$Pick u to simplify when differentiated and dv to integrate cleanly, then write the full by-parts formula.$$, $$Dropping the remaining integral or reversing signs in the uv - integral v du step.$$, $$integration-by-parts$$),
  ($$ap_calculus_ab$$,6,$$6.14$$,$$Selecting Techniques for Antidifferentiation$$,$$very-important$$,$$very-important$$,$$This topic is about choosing a valid integration method based on the structure of the integrand.$$, $$AP integration questions often reward recognizing whether basic rules, substitution, algebraic rewrite, or another technique is appropriate.$$, $$You earn points by matching the integrand structure to an antidifferentiation procedure before calculating.$$, $$Classify the integrand first: basic reverse rule, composite needing substitution, rational needing rewrite, or product needing another technique.$$, $$Forcing substitution or a memorized pattern when the integrand structure points elsewhere.$$, $$selecting-antidifferentiation-techniques$$),
  ($$ap_calculus_ab$$,7,$$7.1$$,$$Modeling Situations with Differential Equations$$,$$very-important$$,$$very-important$$,$$Differential equations model situations where a quantity's rate of change depends on variables in the situation.$$, $$They connect derivatives to prediction, growth, decay, and accumulation-based modeling.$$, $$You earn points by translating verbal rate relationships into equations involving dy/dx or related notation.$$, $$Identify the quantity, identify what controls its rate, then write the differential equation with the correct variables.$$, $$Writing a formula for y instead of an equation for the rate of change.$$, $$modeling-differential-equations$$),
  ($$ap_calculus_ab$$,7,$$7.2$$,$$Verifying Solutions for Differential Equations$$,$$very-important$$,$$very-important$$,$$A proposed solution satisfies a differential equation if its derivative matches the rate expression after substitution.$$, $$Verification points are often direct if students show both the derivative and substitution check.$$, $$You earn points by differentiating the proposed solution and comparing it to the right-hand side of the differential equation.$$, $$Compute dy/dx from the proposed y, substitute y and x into the differential equation, then show they match.$$, $$Checking only the initial condition or only the equation, rather than verifying both when both are asked.$$, $$verifying-differential-equation-solutions$$),
  ($$ap_calculus_ab$$,7,$$7.3$$,$$Sketching Slope Fields$$,$$very-important$$,$$very-important$$,$$A slope field shows small line segments whose slopes come from a differential equation at points in the plane.$$, $$It helps students visualize solution behavior without solving the differential equation exactly.$$, $$You earn points by computing slopes at specified points and drawing segments with correct relative direction and steepness.$$, $$Plug each point into dy/dx, then draw a short segment with that slope at the point.$$, $$Drawing solution curves when the task asks for field segments, or ignoring the sign of the slope.$$, $$slope-fields$$),
  ($$ap_calculus_ab$$,7,$$7.4$$,$$Reasoning Using Slope Fields$$,$$very-important$$,$$very-important$$,$$Slope fields allow students to infer solution behavior, equilibrium behavior, and approximate paths from local slopes.$$, $$AP questions use slope fields to test qualitative reasoning about differential equations.$$, $$You earn points by connecting the displayed segment slopes to whether solutions increase, decrease, level off, or change direction.$$, $$Follow the local directions of the field and describe the solution curve consistent with nearby slopes.$$, $$Reading the slope field as a graph of y-values rather than as directions for solution curves.$$, $$reasoning-with-slope-fields$$),
  ($$ap_calculus_ab$$,7,$$7.5$$,$$Approximating Solutions Using Euler's Method$$,$$very-important$$,$$very-important$$,$$Euler's Method uses repeated tangent-line steps to approximate a solution to a differential equation.$$, $$It is an AP-friendly numerical method where organized tables can secure points.$$, $$You earn points by using the current point to compute slope, multiplying by step size, and updating y at each step.$$, $$Make a row for each step: x, y, slope, delta y, new y.$$, $$Using the slope from the endpoint instead of the current point or skipping intermediate steps.$$, $$eulers-method$$),
  ($$ap_calculus_ab$$,7,$$7.6$$,$$Finding General Solutions Using Separation of Variables$$,$$very-important$$,$$very-important$$,$$Separation of variables solves certain differential equations by placing y terms with dy and x terms with dx before integrating.$$, $$This is a major exact-solution method and connects differential equations back to antiderivatives.$$, $$You earn points by separating variables correctly, integrating both sides, and including the constant of integration.$$, $$Move all y terms to one side and x terms to the other, integrate, then include +C.$$, $$Mixing x and y after separation or omitting the integration constant.$$, $$separation-of-variables-general-solutions$$),
  ($$ap_calculus_ab$$,7,$$7.7$$,$$Finding Particular Solutions Using Initial Conditions and Separation of Variables$$,$$very-important$$,$$very-important$$,$$A particular solution uses an initial condition to determine the constant in a general differential equation solution.$$, $$AP FRQs often award separate points for separation, integration, constant use, and final solution form.$$, $$You earn points by solving generally, substituting the initial condition, determining C, and presenting the particular solution.$$, $$Do not wait until the end mentally: substitute the given point clearly to solve for C.$$, $$Leaving the answer with an undetermined C or applying the initial condition to the derivative instead of the solution.$$, $$separation-of-variables-particular-solutions$$),
  ($$ap_calculus_ab$$,7,$$7.8$$,$$Exponential Models with Differential Equations$$,$$very-important$$,$$very-important$$,$$Exponential models arise when a quantity changes at a rate proportional to the quantity itself.$$, $$They appear in growth, decay, and rate-model contexts across AP Calculus.$$, $$You earn points by recognizing dy/dt = ky structure and interpreting the sign and meaning of k in context.$$, $$Look for rate proportional to amount, then write or use the exponential solution model with the initial value.$$, $$Using a linear model when the rate depends on the current amount.$$, $$exponential-differential-equation-models$$),
  ($$ap_calculus_ab$$,7,$$7.9$$,$$Logistic Models with Differential Equations$$,$$somewhat-important$$,$$somewhat-important$$,$$Logistic models describe growth that slows as a population approaches a carrying capacity.$$, $$They test whether students can interpret rate factors, equilibrium values, and limiting behavior in a model.$$, $$You earn points by identifying carrying capacity, growth intervals, and how the rate changes with population size.$$, $$Use the factors in the differential equation to find equilibria and describe behavior relative to carrying capacity.$$, $$Treating logistic growth as ordinary exponential growth with no upper limit.$$, $$logistic-differential-equation-models$$),
  ($$ap_calculus_ab$$,8,$$8.1$$,$$Finding the Average Value of a Function on an Interval$$,$$very-important$$,$$very-important$$,$$Average value uses a definite integral divided by interval length to find the function's mean height over an interval.$$, $$It is a common integration interpretation that is distinct from average rate of change.$$, $$You earn points by setting up 1/(b-a) times the integral from a to b of f(x) dx and interpreting the result with correct units.$$, $$Write the formula before evaluating so the interval length and integral are both visible.$$, $$Confusing average value with slope between endpoints.$$, $$average-value-of-a-function$$),
  ($$ap_calculus_ab$$,8,$$8.2$$,$$Connecting Position, Velocity, and Acceleration Using Integrals$$,$$very-important$$,$$very-important$$,$$Integrals connect velocity to change in position and acceleration to change in velocity.$$, $$Motion questions often mix derivative and integral relationships in the same prompt.$$, $$You earn points by using definite integrals to compute displacement or change in velocity and by distinguishing displacement from distance traveled.$$, $$Identify whether the integral of velocity gives displacement or whether total distance requires integrating speed.$$, $$Reporting displacement when the question asks for total distance traveled.$$, $$motion-with-integrals$$),
  ($$ap_calculus_ab$$,8,$$8.3$$,$$Using Accumulation Functions and Definite Integrals in Applied Contexts$$,$$very-important$$,$$very-important$$,$$Definite integrals in context accumulate rates into total change for quantities like volume, population, temperature, or cost.$$, $$This topic is a direct route to FRQ points because the setup, units, and interpretation can each be assessed.$$, $$You earn points by identifying the rate, integrating over the correct interval, and adding an initial value when the question asks for an amount.$$, $$Use final amount = initial amount + accumulated change when an initial value is given.$$, $$Forgetting the initial amount or attaching the rate's units instead of the accumulated quantity's units.$$, $$applied-definite-integrals$$),
  ($$ap_calculus_ab$$,8,$$8.4$$,$$Finding the Area Between Curves Expressed as Functions of x$$,$$very-important$$,$$very-important$$,$$Area between x-functions uses vertical slices and integrates top function minus bottom function.$$, $$It is a core applications-of-integration task and often appears in multi-part FRQs.$$, $$You earn points by finding intersection bounds and integrating upper minus lower over each interval.$$, $$Sketch or compare functions to identify top and bottom, then integrate top minus bottom with respect to x.$$, $$Reversing top and bottom or failing to split intervals when the top function changes.$$, $$area-between-curves-x$$),
  ($$ap_calculus_ab$$,8,$$8.5$$,$$Finding the Area Between Curves Expressed as Functions of y$$,$$somewhat-important$$,$$somewhat-important$$,$$Area between y-functions uses horizontal slices and integrates right function minus left function with respect to y.$$, $$This topic extends area reasoning when curves are easier or required to describe as x-functions of y.$$, $$You earn points by using y-bounds and subtracting left from right in the horizontal-slice setup.$$, $$Identify rightmost x and leftmost x as functions of y, then integrate right minus left dy.$$, $$Using dx bounds or top-minus-bottom logic when the setup requires horizontal slices.$$, $$area-between-curves-y$$),
  ($$ap_calculus_ab$$,8,$$8.6$$,$$Finding the Area Between Curves That Intersect at More Than Two Points$$,$$very-important$$,$$very-important$$,$$When curves intersect more than twice, the region may need to be split into intervals with different top-bottom relationships.$$, $$AP tasks often use this to test setup decisions, not just integration skill.$$, $$You earn points by identifying all relevant intersection points, splitting the region, and using the correct subtraction order on each interval.$$, $$Find every intersection, draw or test each interval, then add the separate area integrals.$$, $$Using one integral across the whole interval when the upper and lower functions switch.$$, $$area-between-multiple-intersections$$),
  ($$ap_calculus_ab$$,8,$$8.7$$,$$Volumes with Cross Sections: Squares and Rectangles$$,$$very-important$$,$$very-important$$,$$Cross-section volume sums areas of slices whose square or rectangular dimensions are based on a region in the base.$$, $$This is a high-value setup topic where geometric interpretation earns points before integration is evaluated.$$, $$You earn points by identifying the slice width, writing the cross-sectional area formula, and integrating that area over the correct bounds.$$, $$Base of slice from the region first, area formula second, integral of area last.$$, $$Integrating a length instead of an area or using the wrong side length for the cross section.$$, $$cross-section-volumes-squares-rectangles$$),
  ($$ap_calculus_ab$$,8,$$8.8$$,$$Volumes with Cross Sections: Triangles and Semicircles$$,$$somewhat-important$$,$$somewhat-important$$,$$Triangular and semicircular cross sections use geometry formulas to turn base lengths into slice areas.$$, $$These questions reward students who connect region geometry to the correct area formula instead of memorizing one volume pattern.$$, $$You earn points by identifying the cross-section shape, substituting the region's base length into the correct area formula, and integrating.$$, $$Write the shape formula before substituting the base length from the graph or equations.$$, $$Using square cross-section area when the problem specifies triangles or semicircles.$$, $$cross-section-volumes-triangles-semicircles$$),
  ($$ap_calculus_ab$$,8,$$8.9$$,$$Volume with Disc Method: Revolving Around the x- or y-Axis$$,$$very-important$$,$$very-important$$,$$The disc method finds volume by integrating circular cross-sectional areas when a region rotates around a coordinate axis without a hole.$$, $$It connects geometry, radius choice, and integration in a common AP applications pattern.$$, $$You earn points by identifying the radius perpendicular to the axis of rotation and integrating pi times radius squared over the correct bounds.$$, $$Draw the radius from the axis to the curve, then write pi r^2 for the slice area.$$, $$Using diameter as radius or choosing a radius parallel to the axis of rotation.$$, $$disc-method-coordinate-axes$$),
  ($$ap_calculus_ab$$,8,$$8.10$$,$$Volume with Disc Method: Revolving Around Other Axes$$,$$somewhat-important$$,$$somewhat-important$$,$$Disc method around a non-coordinate axis still uses circular slices, but the radius is a distance to the given line of rotation.$$, $$This topic tests whether students understand radius as distance rather than as the function value itself.$$, $$You earn points by expressing the radius as the distance from the curve to the rotation axis and integrating pi r^2.$$, $$Write radius = distance to axis, then square it inside pi r^2.$$, $$Using f(x) as the radius when the axis is shifted away from the coordinate axis.$$, $$disc-method-other-axes$$),
  ($$ap_calculus_ab$$,8,$$8.11$$,$$Volume with Washer Method: Revolving Around the x- or y-Axis$$,$$very-important$$,$$very-important$$,$$The washer method finds volume when rotation creates an outer radius and an inner radius.$$, $$It is a common AP setup where the main points come from correct outer-minus-inner structure.$$, $$You earn points by identifying both radii and integrating pi times outer radius squared minus inner radius squared.$$, $$Draw both distances from the axis, label outer and inner, then write pi(R^2-r^2).$$, $$Subtracting radii before squaring or reversing inner and outer radii.$$, $$washer-method-coordinate-axes$$),
  ($$ap_calculus_ab$$,8,$$8.12$$,$$Volume with Washer Method: Revolving Around Other Axes$$,$$somewhat-important$$,$$somewhat-important$$,$$Washer method around a shifted axis uses outer and inner radii measured as distances to that axis.$$, $$It extends washer reasoning and often tests careful setup more than difficult integration.$$, $$You earn points by defining both shifted-axis distances and preserving the pi(R^2-r^2) structure.$$, $$Measure each radius from the rotation line, not from the coordinate axis, then subtract areas.$$, $$Forgetting to adjust radii for the shifted axis.$$, $$washer-method-other-axes$$),
  ($$ap_calculus_ab$$,8,$$8.13$$,$$Arc Length of a Smooth Planar Curve$$,$$somewhat-important$$,$$somewhat-important$$,$$Arc length uses an integral built from the derivative to measure the length of a smooth curve.$$, $$It is a lower-frequency but conceptually useful application connecting derivative steepness to accumulated length.$$, $$You earn points by setting up the arc length integral with sqrt(1+(dy/dx)^2) over the correct interval.$$, $$Find the derivative, square it inside the square-root expression, then integrate over the stated bounds.$$, $$Using area under the curve instead of the arc length formula.$$, $$arc-length$$),
  ($$ap_biology$$,2,$$2.1$$,$$Cell Structure and Function$$,$$very-important$$,$$very-important$$,$$Cells contain specialized structures whose shapes and locations support specific biological functions.$$, $$This topic anchors the structure-function reasoning used throughout cell biology, energetics, communication, and heredity.$$, $$You earn points by connecting a cell structure to the process it supports and explaining why that structure helps the process happen.$$, $$Name the structure, name the function, then explain the feature that makes the function possible.$$, $$Listing organelles without connecting structure to function.$$, $$cell-structure-and-function$$),
  ($$ap_biology$$,2,$$2.2$$,$$Cell Size$$,$$very-important$$,$$very-important$$,$$Cell size is constrained by surface area-to-volume ratio and the need to exchange materials efficiently.$$, $$This is an early quantitative biology topic that explains why cells stay small or use adaptations to increase exchange.$$, $$You earn points by connecting size changes to surface area, volume, exchange rate, and limits on cellular function.$$, $$Compare surface area and volume as size changes, then state the effect on exchange efficiency.$$, $$Saying small cells are efficient without explaining the surface area-to-volume relationship.$$, $$cell-size$$),
  ($$ap_biology$$,2,$$2.3$$,$$Plasma Membrane$$,$$very-important$$,$$very-important$$,$$The plasma membrane is a phospholipid bilayer with embedded proteins that separates internal and external environments.$$, $$Membrane structure explains selective permeability, transport, signaling, and compartment boundaries.$$, $$You earn points by connecting phospholipid amphipathic structure and membrane proteins to selective movement or communication.$$, $$Start with bilayer structure, then identify the protein or lipid feature responsible for the observed function.$$, $$Calling the membrane a barrier without explaining selective permeability.$$, $$plasma-membrane$$),
  ($$ap_biology$$,2,$$2.4$$,$$Membrane Permeability$$,$$very-important$$,$$very-important$$,$$Membrane permeability depends on molecule size, polarity, charge, and whether transport proteins are available.$$, $$This topic helps students predict which molecules cross membranes and why.$$, $$You earn points by explaining movement based on molecular properties and membrane composition.$$, $$Ask whether the molecule is small/nonpolar, polar, charged, or large, then decide if a protein is needed.$$, $$Saying molecules cross because the cell needs them instead of because their properties allow it.$$, $$membrane-permeability$$),
  ($$ap_biology$$,2,$$2.5$$,$$Membrane Transport$$,$$very-important$$,$$very-important$$,$$Membrane transport includes passive movement down gradients and active movement requiring energy to move against gradients.$$, $$Transport is central to homeostasis, signaling, and cellular energy use.$$, $$You earn points by identifying the gradient, direction of movement, energy requirement, and protein involvement.$$, $$State high-to-low or low-to-high relative to the gradient, then name passive or active transport.$$, $$Ignoring gradient direction or claiming all protein transport requires ATP.$$, $$membrane-transport$$),
  ($$ap_biology$$,2,$$2.6$$,$$Facilitated Diffusion$$,$$very-important$$,$$very-important$$,$$Facilitated diffusion uses membrane proteins to move substances down their concentration gradients without direct energy input.$$, $$It links protein structure to membrane permeability and homeostasis.$$, $$You earn points by explaining that a specific channel or carrier allows movement down the gradient.$$, $$Name the transport protein type and make clear the movement is passive and down gradient.$$, $$Calling facilitated diffusion active transport because a protein is involved.$$, $$facilitated-diffusion$$),
  ($$ap_biology$$,2,$$2.7$$,$$Tonicity and Osmoregulation$$,$$very-important$$,$$very-important$$,$$Tonicity describes how surrounding solute concentration affects water movement across membranes.$$, $$It is a common AP context for predicting cell volume changes and homeostatic regulation.$$, $$You earn points by identifying the relative solute concentrations, predicting water movement, and explaining the effect on the cell.$$, $$Compare solute inside and outside, then move water toward the higher solute concentration.$$, $$Moving solute instead of water when answering an osmosis question.$$, $$tonicity-and-osmoregulation$$),
  ($$ap_biology$$,2,$$2.8$$,$$Mechanisms of Transport$$,$$very-important$$,$$very-important$$,$$Cells use channels, carriers, pumps, endocytosis, and exocytosis to move materials across membranes.$$, $$Different mechanisms match different molecule types, gradient directions, and energy demands.$$, $$You earn points by choosing the mechanism that fits the substance and explaining why that mechanism is needed.$$, $$Match molecule size and gradient direction to channel, carrier, pump, endocytosis, or exocytosis.$$, $$Naming a mechanism without justifying why the cell would use it for that material.$$, $$transport-mechanisms$$),
  ($$ap_biology$$,2,$$2.9$$,$$Cell Compartmentalization$$,$$very-important$$,$$very-important$$,$$Compartmentalization separates cellular processes into membrane-bound spaces with distinct conditions.$$, $$It explains how eukaryotic cells increase efficiency, regulate reactions, and maintain incompatible environments.$$, $$You earn points by linking a compartment to the process it supports and the advantage of separation.$$, $$Identify the compartment, the process inside it, and the benefit of separating that process.$$, $$Saying organelles are specialized without explaining the advantage of compartment boundaries.$$, $$cell-compartmentalization$$),
  ($$ap_biology$$,2,$$2.10$$,$$Origins of Cell Compartmentalization$$,$$somewhat-important$$,$$somewhat-important$$,$$Endosymbiotic theory explains the origin of mitochondria and chloroplasts from ancestral prokaryotes.$$, $$This topic connects cell structure to evolution and evidence-based biological claims.$$, $$You earn points by citing evidence such as double membranes, circular DNA, ribosomes, or division by binary fission and connecting it to ancestry.$$, $$Name a specific evidence feature and explain how it supports endosymbiosis.$$, $$Listing mitochondria and chloroplasts as examples without providing evidence for their origin.$$, $$origins-of-compartmentalization$$),
  ($$ap_biology$$,3,$$3.1$$,$$Enzymes$$,$$very-important$$,$$very-important$$,$$Enzymes are biological catalysts whose active sites help lower activation energy for specific reactions.$$, $$Enzyme questions connect protein structure, reaction rate, regulation, and environmental conditions.$$, $$You earn points by connecting active-site shape, substrate specificity, and activation energy to reaction outcomes.$$, $$Describe how enzyme structure affects substrate binding and reaction rate.$$, $$Saying enzymes add energy to reactions instead of lowering activation energy.$$, $$enzymes$$),
  ($$ap_biology$$,3,$$3.2$$,$$Environmental Impacts on Enzyme Function$$,$$very-important$$,$$very-important$$,$$Temperature, pH, salinity, and other conditions can alter enzyme shape and activity.$$, $$This topic is a recurring experimental context where students must connect data trends to molecular explanation.$$, $$You earn points by linking environmental change to protein structure, active-site fit, and reaction rate.$$, $$Use data to identify the activity change, then explain it through enzyme shape or denaturation when appropriate.$$, $$Only describing the graph trend without explaining the molecular cause.$$, $$environmental-impacts-on-enzymes$$),
  ($$ap_biology$$,3,$$3.3$$,$$Cellular Energy$$,$$very-important$$,$$very-important$$,$$Cells use energy coupling and ATP to drive processes that require energy input.$$, $$This topic supports understanding of transport, biosynthesis, movement, photosynthesis, and respiration.$$, $$You earn points by explaining how ATP hydrolysis or coupled reactions make an unfavorable process possible.$$, $$Identify the energy-requiring process and connect ATP or coupling to the work being done.$$, $$Saying ATP is energy without explaining how phosphate transfer or coupling supports the process.$$, $$cellular-energy$$),
  ($$ap_biology$$,3,$$3.4$$,$$Photosynthesis$$,$$very-important$$,$$very-important$$,$$Photosynthesis converts light energy into chemical energy stored in sugars through linked light reactions and carbon fixation.$$, $$It connects energy flow, organelle structure, electron transport, carbon cycling, and environmental inputs.$$, $$You earn points by linking inputs, locations, products, and energy transformations across the two major stages.$$, $$Separate light reactions from the Calvin cycle, then connect their products and dependencies.$$, $$Mixing up where oxygen, ATP, NADPH, or sugar are produced.$$, $$photosynthesis$$),
  ($$ap_biology$$,3,$$3.5$$,$$Cellular Respiration$$,$$very-important$$,$$very-important$$,$$Cellular respiration transfers energy from organic molecules to ATP through glycolysis, oxidation steps, and electron transport.$$, $$It is one of the most tested cellular energetics topics and often appears in data and experimental questions.$$, $$You earn points by connecting molecule breakdown, electron carriers, proton gradients, oxygen, and ATP production.$$, $$Track carbon, electrons, and ATP through the process instead of memorizing a list of stages.$$, $$Saying oxygen makes ATP directly instead of explaining its role as final electron acceptor.$$, $$cellular-respiration$$),
  ($$ap_biology$$,4,$$4.1$$,$$Cell Communication$$,$$very-important$$,$$very-important$$,$$Cell communication uses signals, receptors, and responses to coordinate activity across cells.$$, $$It supports explanations of development, immune responses, homeostasis, and environmental response.$$, $$You earn points by connecting signal reception to a cellular response and explaining how specificity is achieved.$$, $$Identify the signal, receptor, target cell, and response in order.$$, $$Saying a signal causes a response without explaining receptor specificity.$$, $$cell-communication$$),
  ($$ap_biology$$,4,$$4.2$$,$$Introduction to Signal Transduction$$,$$very-important$$,$$very-important$$,$$Signal transduction converts an external or internal signal into intracellular molecular changes.$$, $$It is the mechanism that turns communication into altered cell behavior.$$, $$You earn points by explaining the sequence reception -> transduction -> response.$$, $$Use the three-stage chain and place each molecule or event in the correct stage.$$, $$Skipping from signal to response without describing intracellular transduction.$$, $$signal-transduction-introduction$$),
  ($$ap_biology$$,4,$$4.3$$,$$Signal Transduction Pathways$$,$$very-important$$,$$very-important$$,$$Signal transduction pathways often use cascades, phosphorylation, second messengers, and amplification.$$, $$AP questions reward mechanistic explanations of how a small signal produces a larger or specific response.$$, $$You earn points by tracing pathway order and explaining how changes to one component affect downstream response.$$, $$Follow the pathway arrow by arrow and state whether each step activates, inhibits, or amplifies the next.$$, $$Describing every component as simply on or off without linking upstream changes to downstream effects.$$, $$signal-transduction-pathways$$),
  ($$ap_biology$$,4,$$4.4$$,$$Feedback$$,$$very-important$$,$$very-important$$,$$Feedback loops regulate biological systems by using outputs to influence earlier steps.$$, $$Negative feedback supports homeostasis, while positive feedback amplifies a process toward an endpoint.$$, $$You earn points by identifying the variable, stimulus, response, and whether the loop reduces or amplifies the original change.$$, $$Ask whether the response reverses the change or strengthens it, then name negative or positive feedback.$$, $$Calling every control system negative feedback without explaining the direction of the response.$$, $$feedback$$),
  ($$ap_biology$$,4,$$4.5$$,$$Cell Cycle$$,$$very-important$$,$$very-important$$,$$The cell cycle coordinates growth, DNA replication, and division through ordered phases.$$, $$It connects cellular reproduction to inheritance, development, and regulation.$$, $$You earn points by placing events in the correct phase and explaining why ordering matters for accurate division.$$, $$Name the phase and the key event: growth, DNA replication, chromosome separation, or cytokinesis.$$, $$Mixing up DNA replication with chromosome separation.$$, $$cell-cycle$$),
  ($$ap_biology$$,4,$$4.6$$,$$Regulation of Cell Cycle$$,$$very-important$$,$$very-important$$,$$Cell cycle checkpoints and regulatory proteins help prevent division when DNA or cell conditions are not ready.$$, $$This topic links signaling, mutation, cancer, and inheritance of cellular errors.$$, $$You earn points by explaining how checkpoint failure or regulatory disruption changes cell division outcomes.$$, $$Identify the checkpoint or regulator, then state what error it normally prevents.$$, $$Saying cells divide too fast without explaining the failed control mechanism.$$, $$cell-cycle-regulation$$),
  ($$ap_biology$$,5,$$5.1$$,$$Meiosis$$,$$very-important$$,$$very-important$$,$$Meiosis produces haploid gametes through two divisions after one round of DNA replication.$$, $$It is the foundation for inheritance, genetic diversity, and allele segregation.$$, $$You earn points by tracking homologous chromosomes, sister chromatids, ploidy, and gamete outcomes across meiosis I and II.$$, $$Separate meiosis I from meiosis II: homologs separate first, sister chromatids separate second.$$, $$Confusing meiosis with mitosis or losing track of chromosome number changes.$$, $$meiosis$$),
  ($$ap_biology$$,5,$$5.2$$,$$Meiosis and Genetic Diversity$$,$$very-important$$,$$very-important$$,$$Crossing over and independent assortment create genetic variation among gametes.$$, $$This topic explains how sexual reproduction increases variation that later evolution can act on.$$, $$You earn points by connecting a meiotic event to new allele combinations in gametes or offspring.$$, $$Name crossing over or independent assortment and explain the specific source of variation.$$, $$Saying meiosis creates diversity without identifying the mechanism.$$, $$meiosis-and-genetic-diversity$$),
  ($$ap_biology$$,5,$$5.3$$,$$Mendelian Genetics$$,$$very-important$$,$$very-important$$,$$Mendelian genetics predicts inheritance patterns for traits controlled by alleles that segregate and assort.$$, $$It is a common quantitative and reasoning context for connecting meiosis to offspring outcomes.$$, $$You earn points by assigning genotypes, setting up crosses, and interpreting probabilities or phenotypic ratios.$$, $$Define alleles and parental genotypes before building the Punnett square or probability setup.$$, $$Reporting ratios without connecting them to genotype and allele segregation.$$, $$mendelian-genetics$$),
  ($$ap_biology$$,5,$$5.4$$,$$Non-Mendelian Genetics$$,$$very-important$$,$$very-important$$,$$Non-Mendelian patterns include inheritance that does not follow simple dominant-recessive single-gene expectations.$$, $$It broadens genetics reasoning to sex linkage, codominance, incomplete dominance, polygenic traits, and environmental interactions.$$, $$You earn points by identifying the inheritance pattern from evidence and adjusting genotype-to-phenotype reasoning accordingly.$$, $$Use the data pattern to choose the inheritance model before calculating outcomes.$$, $$Forcing every trait into a simple dominant-recessive Punnett square.$$, $$non-mendelian-genetics$$),
  ($$ap_biology$$,5,$$5.5$$,$$Environmental Effects on Phenotype$$,$$very-important$$,$$very-important$$,$$Phenotype results from genotype interacting with environmental conditions.$$, $$This topic prevents oversimplified genetic explanations and connects heredity to variation and natural selection.$$, $$You earn points by explaining how an environmental factor changes gene expression, development, or observable trait value.$$, $$State genotype potential and then explain how the environment shifts the phenotype.$$, $$Claiming the environment changes the DNA sequence when the prompt describes phenotype plasticity.$$, $$environmental-effects-on-phenotype$$),
  ($$ap_biology$$,6,$$6.1$$,$$DNA and RNA Structure$$,$$very-important$$,$$very-important$$,$$DNA and RNA are nucleic acids with nucleotide sequences, sugar-phosphate backbones, and base-pairing rules.$$, $$Structure explains information storage, copying, transcription, and translation.$$, $$You earn points by connecting base sequence, complementarity, directionality, and DNA/RNA differences to biological function.$$, $$Use structure-function language: base order stores information and base pairing enables accurate copying or expression.$$, $$Saying DNA stores information without explaining sequence or base pairing.$$, $$dna-and-rna-structure$$),
  ($$ap_biology$$,6,$$6.2$$,$$DNA Replication$$,$$very-important$$,$$very-important$$,$$DNA replication copies genetic information using complementary base pairing and enzyme-coordinated strand synthesis.$$, $$It supports inheritance, cell division, mutation reasoning, and biotechnology.$$, $$You earn points by explaining template strands, complementary nucleotides, directionality, and enzyme roles in accurate copying.$$, $$Describe how each original strand guides a new complementary strand.$$, $$Saying DNA duplicates without explaining templating or complementary base pairing.$$, $$dna-replication$$),
  ($$ap_biology$$,6,$$6.3$$,$$Transcription and RNA Processing$$,$$very-important$$,$$very-important$$,$$Transcription produces RNA from a DNA template, and RNA processing modifies eukaryotic transcripts before translation.$$, $$This topic connects genetic information to gene expression and regulation.$$, $$You earn points by distinguishing template DNA, mRNA product, RNA polymerase, and processing steps such as splicing when relevant.$$, $$Track information flow from DNA template to RNA sequence, then mention processing if the organism or prompt requires it.$$, $$Confusing transcription with translation or treating introns as protein-coding sequences.$$, $$transcription-and-rna-processing$$),
  ($$ap_biology$$,6,$$6.4$$,$$Translation$$,$$very-important$$,$$very-important$$,$$Translation uses ribosomes, mRNA codons, tRNA anticodons, and amino acids to build polypeptides.$$, $$It completes the flow from genetic information to protein structure and function.$$, $$You earn points by connecting codon sequence to amino acid sequence and explaining the roles of ribosome and tRNA.$$, $$Read mRNA codons in order and connect each codon to an amino acid carried by tRNA.$$, $$Using the DNA template directly as the codon sequence without transcribing to mRNA.$$, $$translation$$),
  ($$ap_biology$$,6,$$6.5$$,$$Regulation of Gene Expression$$,$$very-important$$,$$very-important$$,$$Cells regulate gene expression by controlling when and how much gene product is made.$$, $$Regulation explains specialization, response to environment, development, and efficient resource use.$$, $$You earn points by identifying the control point and explaining how it changes mRNA or protein production.$$, $$State whether regulation affects transcription, RNA processing, translation, or protein activity, then explain the output change.$$, $$Saying a gene is turned on or off without identifying the regulatory mechanism or product effect.$$, $$gene-expression-regulation$$),
  ($$ap_biology$$,6,$$6.6$$,$$Gene Expression and Cell Specialization$$,$$very-important$$,$$very-important$$,$$Different cell types can contain the same genome but express different genes.$$, $$This topic connects regulation to development and explains how specialized cells perform different functions.$$, $$You earn points by explaining that selective gene expression produces different proteins and therefore different cell functions.$$, $$Connect gene expression pattern -> protein set -> specialized cell function.$$, $$Claiming specialized cells have different DNA when the prompt concerns differential gene expression.$$, $$gene-expression-and-specialization$$),
  ($$ap_biology$$,6,$$6.7$$,$$Mutations$$,$$very-important$$,$$very-important$$,$$Mutations are changes in genetic information that can alter RNA, protein sequence, protein function, or phenotype.$$, $$They connect molecular biology to inheritance, disease, variation, and evolution.$$, $$You earn points by tracing the effect of a mutation from DNA change to codon, amino acid, protein structure, and phenotype when appropriate.$$, $$Follow the chain: DNA mutation -> RNA/codon change -> amino acid or regulation change -> functional effect.$$, $$Stopping at mutation happened without explaining the downstream consequence.$$, $$mutations$$),
  ($$ap_biology$$,6,$$6.8$$,$$Biotechnology$$,$$somewhat-important$$,$$somewhat-important$$,$$Biotechnology uses molecular tools to analyze, modify, or compare DNA and gene expression.$$, $$It often appears in experimental and data questions about genes, inheritance, and evidence.$$, $$You earn points by explaining what the tool measures or changes and how the result supports a biological claim.$$, $$Identify the method's input, output, and interpretation before answering the claim.$$, $$Naming a technique without explaining what the data show.$$, $$biotechnology$$),
  ($$ap_biology$$,7,$$7.1$$,$$Introduction to Natural Selection$$,$$very-important$$,$$very-important$$,$$Natural selection occurs when heritable variation affects survival or reproduction in a particular environment.$$, $$This is the core mechanism linking variation to evolutionary change.$$, $$You earn points by connecting variation, heritability, differential fitness, and allele frequency change.$$, $$Use the chain: variation exists -> some variants improve fitness -> those alleles become more common.$$, $$Saying organisms adapt because they need to change.$$, $$natural-selection-introduction$$),
  ($$ap_biology$$,7,$$7.2$$,$$Natural Selection$$,$$very-important$$,$$very-important$$,$$Natural selection changes population traits over generations because individuals with certain heritable traits leave more offspring.$$, $$It is one of the most important AP Biology reasoning patterns and appears across data, experimental, and explanation tasks.$$, $$You earn points by explaining selection pressure, fitness differences, inheritance, and population-level change over time.$$, $$Describe what is selected, why it affects reproductive success, and how the population changes.$$, $$Describing individual organisms evolving during their lifetimes.$$, $$natural-selection$$),
  ($$ap_biology$$,7,$$7.3$$,$$Artificial Selection$$,$$somewhat-important$$,$$somewhat-important$$,$$Artificial selection occurs when humans choose which traits are favored for breeding.$$, $$It provides a clear comparison case for natural selection and helps explain rapid trait shifts.$$, $$You earn points by identifying the human-selected trait and explaining how breeding changes trait or allele frequencies over generations.$$, $$Name the selected trait, who selects it, and how reproduction changes the population.$$, $$Calling artificial selection unnatural and missing the inheritance mechanism.$$, $$artificial-selection$$),
  ($$ap_biology$$,7,$$7.4$$,$$Population Genetics$$,$$very-important$$,$$very-important$$,$$Population genetics studies allele frequencies and how evolutionary forces change genetic composition.$$, $$It gives students a quantitative way to reason about evolution rather than only describing traits.$$, $$You earn points by calculating or interpreting allele and genotype frequencies and linking changes to evolutionary mechanisms.$$, $$Define the population and allele frequencies before deciding whether they changed.$$, $$Confusing genotype frequency with allele frequency.$$, $$population-genetics$$),
  ($$ap_biology$$,7,$$7.5$$,$$Hardy-Weinberg Equilibrium$$,$$very-important$$,$$very-important$$,$$Hardy-Weinberg equilibrium is a null model for genotype frequencies when specific evolutionary conditions are met.$$, $$It is a high-yield quantitative topic for detecting whether evolution is occurring in a population.$$, $$You earn points by using p + q = 1 and p^2 + 2pq + q^2 = 1 and interpreting departures from expected frequencies.$$, $$Identify p and q carefully, calculate genotype frequencies, then compare observed and expected values.$$, $$Taking the square root of the wrong frequency or forgetting that 2pq is the heterozygote frequency.$$, $$hardy-weinberg-equilibrium$$),
  ($$ap_biology$$,7,$$7.6$$,$$Evidence of Evolution$$,$$very-important$$,$$very-important$$,$$Evidence for evolution includes fossils, molecular similarities, anatomical structures, biogeography, and observed population change.$$, $$AP questions reward using evidence to support a claim about relatedness or change over time.$$, $$You earn points by naming specific evidence and explaining how it supports common ancestry or evolutionary change.$$, $$Use claim-evidence-reasoning: state the evolutionary claim, cite the evidence, then explain the connection.$$, $$Listing evidence types without tying them to the claim.$$, $$evidence-of-evolution$$),
  ($$ap_biology$$,7,$$7.7$$,$$Common Ancestry$$,$$very-important$$,$$very-important$$,$$Common ancestry means groups share an ancestral lineage, often inferred from molecular or structural similarities.$$, $$It connects evolution to phylogeny, comparative biology, and DNA evidence.$$, $$You earn points by using similarities and differences to infer relative relatedness or shared ancestry.$$, $$Compare the evidence and state which organisms share a more recent common ancestor and why.$$, $$Saying similar organisms are related without explaining what evidence supports recency of ancestry.$$, $$common-ancestry$$),
  ($$ap_biology$$,7,$$7.8$$,$$Continuing Evolution$$,$$very-important$$,$$very-important$$,$$Evolution continues when allele frequencies keep changing under mutation, selection, drift, or gene flow.$$, $$This topic helps students explain modern examples such as resistance, emerging traits, and changing environments.$$, $$You earn points by identifying the evolutionary force and explaining how it changes allele frequencies over generations.$$, $$Name the force causing change and connect it to allele-frequency shifts, not individual need.$$, $$Describing short-term acclimation as evolution without heritable population change.$$, $$continuing-evolution$$),
  ($$ap_biology$$,7,$$7.9$$,$$Phylogeny$$,$$very-important$$,$$very-important$$,$$Phylogenies represent hypotheses about evolutionary relationships among groups.$$, $$They are common data displays for interpreting relatedness, ancestry, and trait evolution.$$, $$You earn points by reading nodes as common ancestors and using branching patterns, not tip order, to infer relationships.$$, $$Find the most recent common ancestor on the tree before comparing relatedness.$$, $$Comparing organisms by how close their labels appear at the tips instead of by shared nodes.$$, $$phylogeny$$),
  ($$ap_biology$$,7,$$7.10$$,$$Speciation$$,$$very-important$$,$$very-important$$,$$Speciation occurs when populations become reproductively isolated and diverge into separate species.$$, $$It connects evolutionary mechanisms to biodiversity and lineage branching.$$, $$You earn points by explaining the isolating barrier, reduced gene flow, divergence, and reproductive isolation.$$, $$State what separates the populations and how separation leads to accumulated differences.$$, $$Saying two species form because organisms choose different traits without explaining isolation and divergence.$$, $$speciation$$),
  ($$ap_biology$$,7,$$7.11$$,$$Variations in Populations$$,$$very-important$$,$$very-important$$,$$Variation in populations comes from mutation, recombination, and other sources of genetic difference.$$, $$Natural selection can only act on existing heritable variation, so this topic supports nearly every evolution explanation.$$, $$You earn points by identifying the source of variation and explaining how it creates differences selection or drift can act on.$$, $$Connect the variation source to heritable differences among individuals.$$, $$Saying the environment creates needed mutations for a trait.$$, $$population-variation$$),
  ($$ap_biology$$,7,$$7.12$$,$$Origins of Life on Earth$$,$$somewhat-important$$,$$somewhat-important$$,$$Origins-of-life questions address hypotheses about early conditions and the emergence of biological molecules and cells.$$, $$This is lower frequency but helps students distinguish evidence-supported hypotheses from unsupported claims.$$, $$You earn points by connecting early Earth conditions, chemical building blocks, and evidence to a plausible step in life's origin.$$, $$State the hypothesis and the evidence or condition that supports it.$$, $$Making a certainty claim where the question asks for evidence-based hypothesis reasoning.$$, $$origins-of-life$$),
  ($$ap_biology$$,8,$$8.1$$,$$Responses to the Environment$$,$$very-important$$,$$very-important$$,$$Organisms respond to environmental stimuli through behavioral, physiological, or developmental changes.$$, $$This topic connects ecology to regulation, communication, and fitness.$$, $$You earn points by linking a stimulus to a response and explaining how the response affects survival, reproduction, or homeostasis.$$, $$Identify stimulus, response, and biological advantage in the same answer.$$, $$Describing behavior without explaining its effect on fitness or regulation.$$, $$responses-to-environment$$),
  ($$ap_biology$$,8,$$8.2$$,$$Energy Flow Through Ecosystems$$,$$very-important$$,$$very-important$$,$$Energy flows through ecosystems from producers to consumers and is lost as heat at each transfer.$$, $$It is a major ecology concept that supports food webs, trophic pyramids, and productivity reasoning.$$, $$You earn points by tracing energy movement and explaining why available energy decreases at higher trophic levels.$$, $$Follow energy from source to trophic level and account for loss at each transfer.$$, $$Treating energy as recycled like matter.$$, $$energy-flow-through-ecosystems$$),
  ($$ap_biology$$,8,$$8.3$$,$$Population Ecology$$,$$very-important$$,$$very-important$$,$$Population ecology studies population size, growth, carrying capacity, and factors that affect population change.$$, $$It provides graph and model contexts for interpreting ecological data.$$, $$You earn points by connecting birth, death, immigration, emigration, resources, and carrying capacity to population trends.$$, $$Read the graph or model first, then identify which factor changes population size.$$, $$Calling every population increase exponential without checking limiting factors.$$, $$population-ecology$$),
  ($$ap_biology$$,8,$$8.4$$,$$Effect of Density of Populations$$,$$very-important$$,$$very-important$$,$$Population density affects competition, disease spread, predation, and resource availability.$$, $$This topic helps students distinguish density-dependent effects from density-independent events.$$, $$You earn points by explaining how the effect changes as population density changes and what that does to growth or survival.$$, $$Ask whether the factor becomes stronger when the population is more crowded.$$, $$Mislabeling weather or natural disasters as density-dependent just because populations are affected.$$, $$population-density-effects$$),
  ($$ap_biology$$,8,$$8.5$$,$$Community Ecology$$,$$very-important$$,$$very-important$$,$$Community ecology studies interactions among species, including competition, predation, mutualism, parasitism, and succession.$$, $$It connects species interactions to population outcomes and ecosystem structure.$$, $$You earn points by identifying the interaction type and explaining the effect on each species or on community composition.$$, $$Name the interaction and state the effect on each participant using evidence from the prompt.$$, $$Naming an interaction without explaining who benefits, is harmed, or is unaffected.$$, $$community-ecology$$),
  ($$ap_biology$$,8,$$8.6$$,$$Biodiversity$$,$$very-important$$,$$very-important$$,$$Biodiversity includes genetic, species, and ecosystem diversity.$$, $$It supports ecosystem resilience, adaptation potential, and conservation reasoning.$$, $$You earn points by connecting the type of biodiversity to stability, resilience, or response to environmental change.$$, $$Specify genetic, species, or ecosystem diversity, then explain the consequence of more or less diversity.$$, $$Saying biodiversity is good without explaining the mechanism or level of diversity.$$, $$biodiversity$$),
  ($$ap_biology$$,8,$$8.7$$,$$Disruptions in Ecosystems$$,$$very-important$$,$$very-important$$,$$Disruptions such as habitat change, invasive species, climate shifts, and pollution can alter ecosystem structure and function.$$, $$AP ecology questions often ask students to predict effects and justify them from food webs, population data, or biodiversity patterns.$$, $$You earn points by tracing the disruption through direct and indirect effects on populations, interactions, and ecosystem processes.$$, $$Identify the first affected component, then follow consequences through the system using evidence.$$, $$Making a vague claim that the ecosystem is harmed without tracing a specific mechanism.$$, $$ecosystem-disruptions$$)
)
insert into app.topic_point_briefs (
  subject_key, unit_number, topic_code, title, class_importance, exam_importance,
  what_it_is, why_it_matters, how_points_are_earned, answer_move,
  common_point_loss, learn_more_path, practice_subject_key, practice_unit_number,
  practice_topic_code, status, published_at
)
select
  subject_key,
  unit_number,
  topic_code,
  title,
  class_importance,
  exam_importance,
  what_it_is,
  why_it_matters,
  how_points_are_earned,
  answer_move,
  common_point_loss,
  '/learn/' || replace(subject_key, '_', '-') || '/unit-' || unit_number::text || '/' || learn_more_slug,
  subject_key,
  unit_number,
  topic_code,
  'published',
  now()
from brief_seed
on conflict (subject_key, topic_code) do update
set
  unit_number = excluded.unit_number,
  title = excluded.title,
  class_importance = excluded.class_importance,
  exam_importance = excluded.exam_importance,
  what_it_is = excluded.what_it_is,
  why_it_matters = excluded.why_it_matters,
  how_points_are_earned = excluded.how_points_are_earned,
  answer_move = excluded.answer_move,
  common_point_loss = excluded.common_point_loss,
  learn_more_path = excluded.learn_more_path,
  practice_subject_key = excluded.practice_subject_key,
  practice_unit_number = excluded.practice_unit_number,
  practice_topic_code = excluded.practice_topic_code,
  status = excluded.status,
  published_at = excluded.published_at,
  updated_at = now();

do $$
declare
  v_seed_count integer;
begin
  select count(*) into v_seed_count from app.topic_point_briefs
  where subject_key in ('ap_calculus_ab', 'ap_biology')
    and status = 'published';

  if v_seed_count <> 145 then
    raise exception 'expected 145 published AP Calculus AB + AP Biology topic point briefs, found %', v_seed_count;
  end if;
end $$;

commit;
